package vn.smartprop.modules.messaging;
import java.time.Instant;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import vn.smartprop.modules.auth.AccountAccess;
import vn.smartprop.common.*;
import vn.smartprop.modules.property.*;
import vn.smartprop.modules.user.*;
@Service @Transactional(readOnly=true)
public class MessagingService {
    private final JdbcTemplate jdbc;private final AccountAccess access;private final PropertyService properties;private final UserRepository users;private final boolean enabled;private final PropertyRepository propertyRows;
    public record Conversation(String id,String propertyId,Long inquirerId,Long brokerId,Instant updatedAt,long unreadCount) {}
    public record Message(String id,long cursor,Long senderId,String body,Instant createdAt) {@Override public String toString(){return "Message[redacted]";}}
    public record Slice(List<Message> items,long nextCursor,boolean hasMore) {}
    public MessagingService(JdbcTemplate jdbc,AccountAccess access,PropertyService properties,UserRepository users,PropertyRepository propertyRows,@Value("${app.messaging.enabled:false}") boolean enabled){this.jdbc=jdbc;this.access=access;this.properties=properties;this.users=users;this.enabled=enabled;this.propertyRows=propertyRows;}
    private void ready(Long actor){access.active(actor);if(!enabled)throw new ApiException(503,"FEATURE_DISABLED","Messaging disabled");}
    private org.springframework.jdbc.core.RowMapper<Conversation> conversation(){return (r,n)->new Conversation(r.getString("id"),r.getString("property_id"),r.getLong("inquirer_id"),r.getLong("broker_id"),r.getTimestamp("updated_at").toInstant(),r.getLong("unread_count"));}
    private org.springframework.jdbc.core.RowMapper<Message> message(){return (r,n)->new Message(r.getString("id"),r.getLong("sequence"),r.getLong("sender_id"),r.getString("body"),r.getTimestamp("created_at").toInstant());}
    private String select(){return "SELECT c.*,(SELECT COUNT(*) FROM messages m WHERE m.conversation_id=c.id AND m.sender_id<>p.user_id AND m.sequence>p.last_read_sequence) unread_count FROM conversations c JOIN conversation_participants p ON p.conversation_id=c.id ";}
    private Conversation allowed(Long actor,String id,boolean lock){ready(actor);id=ApiInputs.uuid(id);var result=jdbc.query(select()+"WHERE c.id=? AND p.user_id=?"+(lock?" FOR UPDATE":""),conversation(),id,actor);if(result.isEmpty())throw ApiInputs.missing();return result.get(0);}
    @Transactional public Conversation create(Long actor,String property){ready(actor);property=ApiInputs.uuid(property);jdbc.query("SELECT id FROM properties WHERE id=? FOR UPDATE",(r,n)->r.getString(1),property);var p=propertyRows.lockById(property).orElseThrow(ApiInputs::missing);if(!PropertyService.visible(p,Instant.now()))throw ApiInputs.missing();if(Objects.equals(p.ownerId,actor))throw ApiInputs.forbidden();var owner=users.findById(p.ownerId).orElseThrow(ApiInputs::missing);if(owner.deletedAt!=null||owner.status!=User.Status.ACTIVE)throw ApiInputs.missing();var existing=jdbc.query("SELECT id FROM conversations WHERE property_id=? AND inquirer_id=? AND broker_id=? FOR UPDATE",(r,n)->r.getString(1),property,actor,p.ownerId);if(!existing.isEmpty())return allowed(actor,existing.get(0),false);String id=UUID.randomUUID().toString();jdbc.update("INSERT INTO conversations(id,property_id,inquirer_id,broker_id) VALUES(?,?,?,?)",id,property,actor,p.ownerId);jdbc.update("INSERT INTO conversation_participants(conversation_id,user_id) VALUES(?,?),(?,?)",id,actor,id,p.ownerId);return allowed(actor,id,false);}
    public PageResponse<Conversation> list(Long actor,int page,int size){ready(actor);ApiInputs.newest(page,size);long count=jdbc.queryForObject("SELECT COUNT(*) FROM conversation_participants WHERE user_id=?",Long.class,actor);var rows=jdbc.query(select()+"WHERE p.user_id=? ORDER BY c.updated_at DESC,c.id DESC LIMIT ? OFFSET ?",conversation(),actor,size,(long)page*size);return new PageResponse<>(rows,page,size,count,(int)((count+size-1)/size));}
    public Slice messages(Long actor,String id,long after,int limit){id=ApiInputs.uuid(id);allowed(actor,id,false);if(after<0||limit<1||limit>100)throw ApiInputs.bad("Invalid cursor/limit");var rows=jdbc.query("SELECT * FROM messages WHERE conversation_id=? AND sequence>? ORDER BY sequence LIMIT ?",message(),id,after,limit+1);boolean more=rows.size()>limit;var items=List.copyOf(more?rows.subList(0,limit):rows);return new Slice(items,items.isEmpty()?after:items.get(items.size()-1).cursor(),more);}
    @Transactional public Message send(Long actor,String id,String clientId,String body){id=ApiInputs.uuid(id);var peek=allowed(actor,id,false);propertyRows.lockById(peek.propertyId()).orElseThrow(ApiInputs::missing);var c=allowed(actor,id,true);clientId=ApiInputs.uuid(clientId);if(body==null||body.isBlank()||body.length()>4000)throw ApiInputs.bad("Message length 1-4000");body=body.strip();var previous=jdbc.query("SELECT * FROM messages WHERE conversation_id=? AND sender_id=? AND client_message_id=? FOR UPDATE",message(),id,actor,clientId);if(!previous.isEmpty()){if(!previous.get(0).body().equals(body))throw ApiInputs.conflict("clientMessageId already used");return previous.get(0);}
        Property p=propertyRows.lockById(c.propertyId()).orElseThrow(ApiInputs::missing);if(!PropertyService.visible(p,Instant.now()))throw ApiInputs.conflict("Listing no longer accepts messages");for(Long user:List.of(c.inquirerId(),c.brokerId())){var u=users.findById(user).orElseThrow(ApiInputs::missing);if(u.deletedAt!=null||u.status!=User.Status.ACTIVE)throw ApiInputs.conflict("Participant unavailable");}
        String messageId=UUID.randomUUID().toString();jdbc.update("INSERT INTO messages(id,conversation_id,sender_id,client_message_id,body) VALUES(?,?,?,?,?)",messageId,id,actor,clientId,body);jdbc.update("UPDATE conversations SET updated_at=UTC_TIMESTAMP(6) WHERE id=?",id);return jdbc.queryForObject("SELECT * FROM messages WHERE id=?",message(),messageId);
    }
    @Transactional public void read(Long actor,String id,long cursor){id=ApiInputs.uuid(id);allowed(actor,id,true);if(cursor<0)throw ApiInputs.bad("Invalid cursor");Long maximum=jdbc.queryForObject("SELECT COALESCE(MAX(sequence),0) FROM messages WHERE conversation_id=?",Long.class,id);if(cursor>maximum)throw ApiInputs.bad("Cursor beyond conversation");jdbc.update("UPDATE conversation_participants SET last_read_sequence=GREATEST(last_read_sequence,?) WHERE conversation_id=? AND user_id=?",cursor,id,actor);}
}
